def unique_elements(my_list):
    """Returns unique elements in the list, with element type int or str.

    :param my_list: The list of elements to be tested for uniqueness.
    :type my_list: list
    :returns: A new list containing the unique elements of the input list.
    :raises TypeError: If the input list contains elements of mixed types.
    """
    if not my_list:
        return []
    if not isinstance(my_list, list):
        raise TypeError("'my_list' must be a list.")
    if not my_list[0].__class__ in [int, str]:
        raise TypeError("'my_list' must only contain elements of type int or str.")
    my_set = set(my_list)
    if len(my_set) != len(my_list):
        raise TypeError("'my_list' contains elements of mixed types.")
    return list(my_set)

