    def decorator(func):
        cache = {}
        cache_for_typed = {}
        hits, misses = 0, 0

        def plain_wrapper(*args):
            nonlocal cache, hits
            if typed and args in cache_for_typed:
                hits += 1
                return cache_for_typed[args]
            elif args in cache:
                hits += 1
                return cache[args]
            else:
                misses += 1
                result = func(*args)
                if len(cache) > maxsize:
                    cache.popitem(last=False)
                if typed:
