def minimalBases(classes):
    bases = []
    for c in classes:
        if c not in bases:
            bases.append(c)
        else:
            for base in bases:
                if issubclass(c, base):
                    indices = [i for i, v in enumerate(bases) if v == c]
                    for index in indices:
                        bases[index] = base
                        return bases

