def namesAndDescriptions(self, all=False):
    interface = self.__interface__
    names = []
    descriptions = []
    for name in interface:
        if name == "item" and not all:
            continue
        attr = getattr(self.__class__, name)
        if not isinstance(attr, Descriptor):
            continue
        name_and_description = [name, attr.description]
        if attr.getter:
            name_and_description.append("<%s>hGetter" % self.__class__.__name__)
        if attr.setter:
            name_and_description.append("<%s>hSetter" % self.__class__.__name__)
        if attr.getinit:
            name_and_description.append("<%s>hGetInitialiser" % self.__class__.__name__)
        names.append(name_and_description[0])
        descriptions.append(name_and_description[-1])
    return names, descriptions

