def _get_err_indices(self, coord_name):
        """Get error indices corresponding to a coordinate."""

        if not self.doc:
            raise RuntimeError("Cannot get error indices without a document")

        if not coord_name in self.doc.format:
            raise ValueError("Invalid coordinate: " + coord_name)

        indices = []
        for i, ch in enumerate(self.text):
            if ch in ['(', ')', ',', ' ', '\n', '\t']:
                continue
            try:
                int(ch)
                indices.append(i)
            except ValueError:
                continue

        return indices

