def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if len(coord) != len(self.bins):
        raise ValueError("The coordinate must be the same length as the histogram's bins.")

    for i in range(len(coord)):
        if self.bins[i] is None:
            self.bins[i] = [0] * len(self.bins[i])

        if weight is not None:
            self.bins[i][coord[i]] += weight
        else:
            self.bins[i][coord[i]] += 1

