def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Check if the fixity block is a dict
    if not isinstance(fixity, dict):
        raise TypeError("Fixity block should be a dict")

    # Check if the fixity block has the required fields
    if "total" not in fixity:
        raise ValueError("Fixity block should have a 'total' field")

    if "errors" not in fixity:
        raise ValueError("Fixity block should have an 'errors' field")

    if "items" not in fixity:
        raise ValueError("Fixity block should have an 'items' field")

    # Check if the items field is a list
    if not isinstance(fixity["items"], list):
        raise TypeError("Fixity items should be a list")

    # Check if the items field has the required fields
    for item in fixity["items"]:
        if "file" not in item:
            raise ValueError("Fixity item should have a 'file' field")

        if "fixed" not in item:
            raise ValueError("Fixity item should have a 'fixed' field")

    # Check that all referenced files are present in the manifest
    for item in fixity["items"]:
        if item["file"] not in manifest_files:
            raise ValueError("File {} is not present in the manifest".format(item["file"]))

    return fixity

