def absorb(self, args):
    result = []
    for arg in args:
        if arg.is_atom():
            # Skip if already in the result
            if any(arg in expr for expr in result):
                continue
            result.append(arg)
        elif arg.is_disjunction():
            a, b = arg.get_operands()
            # Handling absorption and negative absorption
            if a.is_atom() and b.could_absorb(a, neg=False):
                result.append(a.absorb(b, neg=False))
            elif a.is_atom() and b.could_absorb(a, neg=True):
                result.append(a.absorb(b, neg=True))
            else:
                result.append(arg)
        else:
            result.append(arg)
    return result

