def determineMetaclass(bases, explicit_mc=None):
        # If there is an explicit metaclass, use that one
        if isinstance(explicit_mc, type):
            return explicit_mc
        # If there is only a single metaclass, use that one
        unique = set(base.__class__ for base in bases)
        if len(unique) == 1:
            return next(iter(unique))
        # Get all unique metaclasses and their counts
        classes = [(mc, bases.count(mc)) for mc in unique]
        # If there is only a single class, use that one
        if len(classes) == 1:
            return classes[0][0]
        # Raise a MetaClassError if there are multiple metaclasses
        raise MetaClassError(
            "Cannot determine metaclass from multi-class bases: {}"
            .format(", ".join(map(str, bases)))
        )

